(7176193, 1101782, 138630, '<td valign="top">One of my favorites - love the way he''s superposed on himself.  Most of all I like the tones.</td>', 'One of my favorites - love the way he''s superposed on himself.  Most of all I like the tones.', '2014-02-13 21:41:36.000000', NULL, 1),
(7176194, 1101216, 138630, '<td valign="top">I suppose this could be reflections in shards of glass?  Very straight edged the pieces are though.  It''s like looking through a broken kaleidoscope.  Not that blurry.</td>', 'I suppose this could be reflections in shards of glass?  Very straight edged the pieces are though.  It''s like looking through a broken kaleidoscope.  Not that blurry.', '2014-02-13 21:41:47.000000', NULL, 1),
