(7176216, 1101683, 63218, '<td valign="top">I''ve been look at this for the longest time,  couldn''t see what it was. Then all of a sudden I did see it. I love surprises like this.  If a turtle could put this on her facebook page, she would!</td>', 'I''ve been look at this for the longest time,  couldn''t see what it was. Then all of a sudden I did see it. I love surprises like this.  If a turtle could put this on her facebook page, she would!', '2014-02-13 22:16:55.000000', NULL, 1),
(7176218, 1101581, 108069, '<td valign="top">Nice find. Makes me think of a hidden corner in a Gehry. Well done.</td>', 'Nice find. Makes me think of a hidden corner in a Gehry. Well done.', '2014-02-13 22:28:38.000000', NULL, 1),
(7176220, 1101189, 108069, '<td valign="top">Very polished and well done.</td>', 'Very polished and well done.', '2014-02-13 22:32:05.000000', NULL, 1),
(7176222, 1101294, 108069, '<td valign="top">Makes me think of some samurai art. I know that makes no sense(i) but there it is. Sorry. This is very nice, and the tones are excellent.</td>', 'Makes me think of some samurai art. I know that makes no sense(i) but there it is. Sorry. This is very nice, and the tones are excellent.', '2014-02-13 22:41:34.000000', NULL, 1),
(7176223, 1101786, 108069, '<td valign="top">I am looking for it but not seeing it. Perhaps the frequency is so high the blur is imperceptible. Very clever.</td>', 'I am looking for it but not seeing it. Perhaps the frequency is so high the blur is imperceptible. Very clever.', '2014-02-13 22:45:03.000000', NULL, 1),
(7176224, 1101216, 108069, '<td valign="top">Nice capture. I don''t really get a sense of blur, but it''s certainly a mess. Like a puzzle.</td>', 'Nice capture. I don''t really get a sense of blur, but it''s certainly a mess. Like a puzzle.', '2014-02-13 22:46:43.000000', NULL, 1),
(7176225, 1101682, 108069, '<td valign="top">Smooth and gentle.</td>', 'Smooth and gentle.', '2014-02-13 22:47:22.000000', NULL, 1),
