INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7176233, 1101658, 108069, '<td valign="top">Let''s levitate to the colosseum! Very cool.</td>', 'Let''s levitate to the colosseum! Very cool.', '2014-02-13 22:58:02.000000', NULL, 1),
(7176234, 1101371, 108069, '<td valign="top">Pretty straight forward with a great result.</td>', 'Pretty straight forward with a great result.', '2014-02-13 22:58:26.000000', NULL, 1),
(7176236, 1101728, 100831, '<td valign="top">Stop smiling at me. I know it''s a yellow house.</td>', 'Stop smiling at me. I know it''s a yellow house.', '2014-02-13 23:01:57.000000', NULL, 1),
(7176242, 1101679, 108069, '<td valign="top">Beautiful photo. Contrast is excellent. I''ll be a jerk and suggest the sharp water drops vs. blur creates a predictably stimulating dynamic that conflicts with my personal interpretation of this challenge. I don''t ever grumble like this and I''m embarrassed to even mention it, but presented in the setting of this challenge that is actually one of my first impressions.<br/> <br/>It''s an excellent photo, regardless, and I''m not voting anyway.</td>', 'Beautiful photo. Contrast is excellent. I''ll be a jerk and suggest the sharp water drops vs. blur creates a predictably stimulating dynamic that conflicts with my personal interpretation of this challenge. I don''t ever grumble like this and I''m embarrassed to even mention it, but presented in the setting of this challenge that is actually one of my first impressions. It''s an excellent photo, regardless, and I''m not voting anyway.', '2014-02-13 23:11:45.000000', NULL, 1),
(7176245, 1101680, 108069, '<td valign="top">Pretty sweet ROYGBV going on here.</td>', 'Pretty sweet ROYGBV going on here.', '2014-02-13 23:16:00.000000', NULL, 1),
(7176246, 1101615, 40391, '<td valign="top">Beautiful and intriguing.</td>', 'Beautiful and intriguing.', '2014-02-13 23:16:12.000000', NULL, 1),
(7176247, 1101615, 108069, '<td valign="top">Have been back to this repeatedly. Something very special about it.</td>', 'Have been back to this repeatedly. Something very special about it.', '2014-02-13 23:17:21.000000', NULL, 1),
(7176251, 1100894, 108069, '<td valign="top">I really like the vibrant color vs. colorless. Interesting warped frames. Nice.</td>', 'I really like the vibrant color vs. colorless. Interesting warped frames. Nice.', '2014-02-13 23:23:48.000000', NULL, 1),
(7176253, 1101208, 108069, '<td valign="top">This is great. Makes me think of a dancing/hopping inchworm (or something). Great lines of all kinds.</td>', 'This is great. Makes me think of a dancing/hopping inchworm (or something). Great lines of all kinds.', '2014-02-13 23:26:43.000000', NULL, 1),
(7176254, 1101782, 108069, '<td valign="top">Interesting mismatching silhouettes. Almost a surprise that the man in the distance is actually much, much closer.</td>', 'Interesting mismatching silhouettes. Almost a surprise that the man in the distance is actually much, much closer.', '2014-02-13 23:30:04.000000', NULL, 1),
(7176256, 1101784, 108069, '<td valign="top">This is somehow very defiant, uplifting. The red strip intersecting with the white jacket creates some powerful elements. Great capture.</td>', 'This is somehow very defiant, uplifting. The red strip intersecting with the white jacket creates some powerful elements. Great capture.', '2014-02-13 23:38:03.000000', NULL, 1),
(7176260, 1101040, 136989, '<td valign="top">I like the distorted perspective and spin. Nice balance of dark and light color.  Maybe it''s the hours in front of a computer working and doing school work but I see an angry dinosaur skeleton out to get me.  I''m off to sleep as apparently I need it!</td>', 'I like the distorted perspective and spin. Nice balance of dark and light color.  Maybe it''s the hours in front of a computer working and doing school work but I see an angry dinosaur skeleton out to get me.  I''m off to sleep as apparently I need it!', '2014-02-13 23:48:19.000000', NULL, 1),
(7176263, 1101769, 136989, '<td valign="top">Very pretty colors.  I love the little bursts of highlights.  Looks like I hope my brain will look tomorrow.  Nice valentines colors and little bursts of happiness.  My favorite in this challenge.<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1082013" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/135000-139999/136989/120/Copyrighted_Image_Reuse_Prohibited_1082013.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/135000-139999/136989/120/Copyrighted_Image_Reuse_Prohibited_1082013.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/135000-139999/136989/120/Copyrighted_Image_Reuse_Prohibited_1082013.jpg"/></a></td>', 'Very pretty colors.  I love the little bursts of highlights.  Looks like I hope my brain will look tomorrow.  Nice valentines colors and little bursts of happiness.  My favorite in this challenge.', '2014-02-13 23:49:34.000000', NULL, 1),
(7176264, 1101647, 108069, '<td valign="top">Love the color this produced. A bit too staged for me for this particular challenge, but it''s really well done to get this in camera.</td>', 'Love the color this produced. A bit too staged for me for this particular challenge, but it''s really well done to get this in camera.', '2014-02-13 23:49:40.000000', NULL, 1),
(7176267, 1101783, 136989, '<td valign="top">I like this picture but I do not see it as a great fit for the challenge.  The opening created by the pillars looks like a door to another world and I like how I am being pulled toward it.</td>', 'I like this picture but I do not see it as a great fit for the challenge.  The opening created by the pillars looks like a door to another world and I like how I am being pulled toward it.', '2014-02-13 23:51:39.000000', NULL, 1),
(7176270, 1101636, 108069, '<td valign="top">Great contrast, great scene, great mood. My eyes are playing tricks, or a soul is ascending at 2 o''clock. Not seeing the blurry mess, but it''s a cool photo.</td>', 'Great contrast, great scene, great mood. My eyes are playing tricks, or a soul is ascending at 2 o''clock. Not seeing the blurry mess, but it''s a cool photo.', '2014-02-13 23:54:50.000000', NULL, 1),
